// @ts-nocheck
// สรุปผล ping + เช็คสาย eth0 + ลองต่อ TCP port 502 / 5000 ของ PLC
const HOST = "192.168.0.102";   // SB01 = Seambuffing 4
const PORTS = [502, 5000];
const TMO = 2000;
const txt = String(msg.payload || "");
const m = txt.match(/(\d+) packets transmitted, (\d+) (?:packets )?received/);
const sent = m ? +m[1] : 0, recv = m ? +m[2] : 0;
const rtt = (txt.match(/= [\d.]+\/([\d.]+)\//) || [])[1];
// ip -br link: "eth0  UP  e6:71:..  <BROADCAST,MULTICAST,UP,LOWER_UP>"
const lk = (txt.match(/^eth0\s+(\S+)\s+\S+\s+<([^>]*)>/m) || []);
const link = !lk[0] ? "ไม่พบ eth0" : /NO-CARRIER/.test(lk[2]) || lk[1] === "DOWN" ? "DOWN (ไม่มีสาย/ปลายทางดับ)" : /LOWER_UP/.test(lk[2]) ? "UP (มีสาย)" : lk[1];
const ip = (txt.match(/^eth0\s+\S+\s+(\d+\.\d+\.\d+\.\d+\/\d+)/m) || [])[1] || "ไม่มี IP";

function probe(port) {
    return new Promise(res => {
        const s = new net.Socket(); const t0 = Date.now(); let done = false;
        const end = r => { if (done) return; done = true; s.destroy(); res(port + ": " + r + " (" + (Date.now() - t0) + "ms)"); };
        s.setTimeout(TMO);
        s.once("connect", () => {
            // ต่อติดแล้ว รอดูว่า PLC ตัดสายทันทีไหม
            setTimeout(() => end("เปิด ✓ ต่อได้"), 800);
            s.once("close", () => end("ต่อได้แต่ PLC ตัดสายทันที ✗"));
        });
        s.once("timeout", () => end("timeout ✗ (PLC ไม่ตอบ)"));
        s.once("error", e => end((e.code === "ECONNREFUSED" ? "ปิด ✗ (PLC ปฏิเสธ)" : "error " + e.code)));
        s.connect(port, HOST);
    });
}

(async () => {
    const tcp = [];
    for (const p of PORTS) tcp.push(await probe(p));
    const ok = recv > 0;
    const res = {
        กล่อง: (txt.match(/^HOST=(.*)$/m) || [])[1] || "?",
        เวลา: new Date().toLocaleString("en-GB"),
        eth0: link + " · " + ip,
        ping: HOST + " " + recv + "/" + sent + " ตอบ" + (rtt ? " · เฉลี่ย " + rtt + " ms" : ""),
        tcp: tcp
    };
    const p502 = tcp[0] || "";
    node.status({
        fill: ok && /✓/.test(p502) ? "green" : ok ? "yellow" : "red", shape: "dot",
        text: "ping " + recv + "/" + sent + " | " + p502.replace(/ \(\d+ms\)/, "")
    });
    node.send({ topic: "ping " + HOST, payload: res });
})();
return null;
